27	export const Splash: React.FC<NativeStackScreenProps<Routes, "splash">> = ({
28	  navigation,
29	}) => {
30	  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
31	  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
32	  const hasSeenNotificationsIntro = useAtomValue(
33	    PushNotificationsAtoms.hasSeenNotificationsIntro,
34	  );
35	  const transition = useRef(
36	    animateParallel(
37	      { opacity: [0, 1], translateY: [40, 0] },
38	      { duration: 200 },
39	    ),
40	  ).current;
41	
42	  const checkAuthAndNavigate = async ({
43	    navigation,
44	    hasSeenOnboarding,
45	    hasSeenNotificationsIntro,
46	    screenLockPin,
47	  }: CheckAuthAndNavigateParams) => {
48	    try {
49	      if (Platform.OS === "ios") {
50	        // Register CallKit listeners as early as possible so buffered
51	        // cold-start answer/end actions are captured before navigation.
52	        await CallKitService.setup();
53	      }
54	
55	      // Check if we have stored credentials
56	      if (AuthService.hasStoredCredentials()) {
57	        const sessionRestored = await AuthService.restoreSession();
58	        const isVerified = VerificationService.isDeviceVerified();
59	
60	        if (sessionRestored && !isVerified) {
61	          navigation.replace("confirmIdentity");
62	          return;
63	        }
64	
65	        if (!hasSeenOnboarding) {
66	          navigation.replace("onboarding");
67	          return;
68	        }
69	
70	        if (!hasSeenNotificationsIntro) {
71	          navigation.replace("notificationsIntro");
72	          return;
73	        }
74	
75	        //If there is a screen lock pin, navigate to the verify pin screen
76	        if (screenLockPin && sessionRestored) {
77	          navigation.replace("verifyPin", { isSettingsScreen: false });
78	          return;
79	        }
80	
81	        if (sessionRestored) {
82	          // Start sync — no-op if offline, rooms are served from local cache
83	          AuthService.startSync();
84	
85	          // Check if app was launched by accepting a CallKit call (quit state)
86	          const pendingCall = CallKitService.consumePendingAnsweredCall();
87	          const hasPendingCall = !!pendingCall?.roomId;
88	          if (hasPendingCall && pendingCall) {
89	            await MatrixCore.refreshRoomList();
90	            await MatrixCore.getClient().awaitRoomRemoteEcho(
91	              pendingCall.roomId,
92	            );
93	
94	            navigation.reset({
95	              index: 0,
96	              routes: [{ name: "home" }],
97	            });
98	            setTimeout(() => {
99	              CallOverlayService.openCall(
100	                pendingCall.roomId,
101	                pendingCall.roomName,
102	              );
103	            }, 250);
104	
105	            return;
106	          }
107	
108	          // Check if app was opened from a Notifee notification (quit state)
109	          await NotifeeService.checkInitialNotification();
110	
111	          // Check if app was opened from a notification
112	          const pendingRoomId = NotifeeService.consumePendingRoomId();
113	          await MatrixCore.refreshRoomList();
114	
115	          if (pendingRoomId) {
116	            await MatrixCore.getClient().awaitRoomRemoteEcho(pendingRoomId);
117	
118	            navigation.reset({
119	              index: 1,
120	              routes: [
121	                { name: "home" },
122	                { name: "room", params: { roomId: pendingRoomId } },
123	              ],
124	            });
125	
126	            return;
127	          }
128	
129	          navigation.replace("home");
130	          return;
131	        }
132	      }
133	
134	      await AuthService.initialize(MatrixBaseURL);
135	      setTimeout(() => {
136	        navigation.replace("welcome");
137	      }, 1000);
138	    } catch (error) {
139	      console.warn("Error during auth check:", error);
140	      navigation.replace("welcome");
141	    }
142	  };
143	
144	  useEffect(() => {
145	    transition.start(() =>
146	      checkAuthAndNavigate({
147	        navigation,
148	        hasSeenOnboarding,
149	        hasSeenNotificationsIntro,
150	        screenLockPin,
151	      }),
152	    );
153	  }, [
154	    navigation,
155	    hasSeenOnboarding,
156	    hasSeenNotificationsIntro,
157	    screenLockPin,
158	    transition,
159	  ]);
160	
161	  return (
162	    <ScreenLayout>
163	      <Block
164	        animations={transition.animations}
165	        flex={1}
166	        align="center"
167	        justify="space-between"
168	      >
169	        <Image
170	          source={require("assets/images/logo.png")}
171	          width={88}
172	          height={66}
173	          style={styles.logo}
174	        />
175	        <Text font="Silkscreen-Regular" size={TextSize.medium}>
176	          CLOAK
177	        </Text>
178	      </Block>
179	    </ScreenLayout>
180	  );
181	};
182	
183	const styles = StyleSheet.create({
184	  logo: {
185	    marginVertical: "auto",
186	  },
187	});
