17	const isInitialNotificationContext = (): boolean => {
18	  if (!NavigationContainerRef?.isReady()) {
19	    return true;
20	  }
21	
22	  // If Splash is still on screen the app just launched; defer room navigation
23	  // until after session restoration instead of navigating immediately.
