27	export class NotifeeService {
28	  private static channelId = "local-push-notifications";
29	
30	  // Store pending room navigation for when app is opened from notification
31	  // This is consumed by the Splash screen after session restoration
32	  private static pendingRoomId: string | null = null;
33	
34	  public static init = async () => {
35	    await notifee.createChannel({
36	      id: this.channelId,
37	      name: "Local push notifications",
38	      sound: "default",
39	      importance: AndroidImportance.HIGH,
40	      visibility: AndroidVisibility.PUBLIC,
41	    });
42	
43	    // Handle notification press when app is in foreground
44	    notifee.onForegroundEvent(async (event) => {
45	      if (event.type === EventType.PRESS) {
46	        await this.handleNotificationPress(
47	          event.detail.notification,
48	          isInitialNotificationContext(),
49	        );
50	      }
51	    });
52	  };
53	
54	  /** Must be called at module level in index.js (outside the app) */
55	  public static registerBackgroundEventHandler = () => {
56	    notifee.onBackgroundEvent(async (event) => {
57	      if (event.type === EventType.PRESS) {
58	        await this.handleNotificationPress(
59	          event.detail.notification,
60	          isInitialNotificationContext(),
61	        );
62	      }
63	    });
64	  };
65	
66	  /**
67	   * Call this during cold-start (e.g. Splash screen) to check if the app was
68	   * opened by tapping a Notifee notification from a quit state.
69	   * Stores the pending room ID so Splash can consume it after session restore.
70	   */
71	  public static checkInitialNotification = async () => {
72	    const initialNotification = await notifee.getInitialNotification();
73	    if (initialNotification) {
74	      await this.handleNotificationPress(
75	        initialNotification.notification,
76	        true,
77	      );
78	    }
79	  };
80	
81	  /** Get and clear the pending room navigation (used by Splash screen) */
82	  public static consumePendingRoomId = (): string | null => {
83	    const roomId = this.pendingRoomId;
84	    this.pendingRoomId = null;
85	    return roomId;
86	  };
87	
88	  public static setPendingRoomId = (roomId: string) => {
89	    this.pendingRoomId = roomId;
90	  };
91	
92	  private static handleNotificationPress = async (
93	    notification: Notification | undefined,
94	    isInitialNotification: boolean,
95	  ) => {
96	    const roomId = notification?.data?.room_id;
97	
98	    if (!roomId || typeof roomId !== "string") return;
99	
100	    // For initial notification (cold start), store the room_id
101	    // and let the Splash screen handle navigation after session restoration
102	    if (isInitialNotification) {
103	      this.pendingRoomId = roomId;
104	      return;
105	    }
106	
107	    // Refresh the room list before navigating to ensure it's up to date
108	    try {
109	      await MatrixCore.refreshRoomList();
110	      await MatrixCore.getClient().awaitRoomRemoteEcho(roomId);
111	    } catch {}
112	
113	    // For foreground/background events (app already running), navigate directly to room
114	    NavigationContainerRef.navigate("room", { roomId });
115	  };
